css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; animation: galaxy calc(var(--loader-speed) * 3) linear infinite; }
.loader span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size) * .08); height: calc(var(--loader-size) * .08); margin: calc(var(--loader-size) * -.04) 0 0 calc(var(--loader-size) * -.04); border-radius: 50%; background: var(--accent); }
.loader span:nth-child(1) { transform: rotate(0deg) translateX(calc(var(--loader-size) * .05)); background: var(--accent-2); }
.loader span:nth-child(2) { transform: rotate(45deg) translateX(calc(var(--loader-size) * .1)); }
.loader span:nth-child(3) { transform: rotate(90deg) translateX(calc(var(--loader-size) * .15)); }
.loader span:nth-child(4) { transform: rotate(135deg) translateX(calc(var(--loader-size) * .2)); opacity: .85; }
.loader span:nth-child(5) { transform: rotate(180deg) translateX(calc(var(--loader-size) * .25)); opacity: .7; }
.loader span:nth-child(6) { transform: rotate(225deg) translateX(calc(var(--loader-size) * .3)); opacity: .55; }
.loader span:nth-child(7) { transform: rotate(180deg) translateX(calc(var(--loader-size) * .05)); background: var(--accent-2); }
.loader span:nth-child(8) { transform: rotate(225deg) translateX(calc(var(--loader-size) * .1)); }
.loader span:nth-child(9) { transform: rotate(270deg) translateX(calc(var(--loader-size) * .15)); }
.loader span:nth-child(10) { transform: rotate(315deg) translateX(calc(var(--loader-size) * .2)); opacity: .85; }
.loader span:nth-child(11) { transform: rotate(0deg) translateX(calc(var(--loader-size) * .25)); opacity: .7; }
.loader span:nth-child(12) { transform: rotate(45deg) translateX(calc(var(--loader-size) * .3)); opacity: .55; }
@keyframes galaxy { to { transform: rotate(360deg); } }
